119	    } else if (offset == HTIF_PUTCHAR_OFFSET && len == 1) {
120	      std::putchar(buf[0]);
121	    } else if (offset == HTIF_CMD_OFFSET) {
122	      (len == 8) ? handle_htif_64bit_write(buf)
123	                 : handle_htif_32bit_low_write(buf);
124	    } else if (offset == HTIF_CMD_HIGH_OFFSET && len == 4) {
125	      handle_htif_32bit_high_write(buf);
126	    } else if (offset == INT_TRIGGER_OFFSET && len == 4) {
127	      auto val = unpack<uint32_t>(buf);
128	      spdlog::debug("sim_control: int_trigger = {:#x}", val);
129	      int_trigger.write(val);
130	      // clear the IRQ after one cycle
131	      if (val != 0) {
132	        wait(clk.posedge_event());
133	        int_trigger.write(0);
134	      }
135	    } else {
136	      spdlog::warn("sim_control: spurious write at {:#x}, length {}", addr,
137	                   len);
138	    }
139	  }
140	
141	  void handle_sim_command(uint32_t command)
142	  {
143	    spdlog::info("sim_control: received command {:#x}", command);
144	    switch (static_cast<SimCommand>(command)) {
145	    case SimCommand::NEWLINE:
146	      std::putchar('\n');
147	      break;
148	    case SimCommand::PASSED:
149	    case SimCommand::FINISHED:
150	      spdlog::info("sim_control: Test PASSED");
151	      exits = 0;
152	      break;
153	    case SimCommand::SKIPPED:
154	      spdlog::info("sim_control: Test SKIPPED");
155	      exits = 0;
156	      break;
157	    case SimCommand::FAILED:
158	      spdlog::info("sim_control: Test FAILED");
159	      exits = 1;
160	      break;
161	    case SimCommand::WARNING:
162	      spdlog::warn("sim_control: Test WARNING");
163	      exits = 1;
164	      break;
165	    default:
166	      if (command < 256)
167	        exits = command;
168	      else
169	        spdlog::warn("sim_control: unknown command {:#x}", command);
170	      break;
171	    }
172	  }
173	
174	  template<typename T>
175	  static T unpack(const std::span<uint8_t>& buf)
176	  {
177	    T result = 0;
178	    for (size_t i = 0; i < sizeof(T); ++i)
179	      result |= static_cast<T>(buf[i]) << (i * 8);
180	    return result;
181	  }
182	
183	  void execute_htif_syscall()
184	  {
185	    command_t cmd(partial_htif_command);
186	    if (cmd.device() != 0 || cmd.cmd() != 0) {
187	      spdlog::warn("sim_control: unknown device: #{}", cmd.device());
188	      return;
189	    }
190	    dispatch(cmd);
191	    partial_htif_command = 0;
192	    htif_parts_received = 0;
193	  }
194	
195	  void handle_htif_64bit_write(const std::span<uint8_t>& buf)
196	  {
197	    command_t cmd(unpack<uint64_t>(buf));
198	    if (cmd.device() == 0 && cmd.cmd() == 0)
199	      dispatch(cmd);
200	    else
201	      spdlog::warn("sim_control: unknown device: #{}", cmd.device());
202	  }
203	
204	  void handle_htif_32bit_low_write(const std::span<uint8_t>& buf)
205	  {
206	    partial_htif_command |= unpack<uint32_t>(buf);
207	    if (++htif_parts_received == HTIF_32BIT_PARTS)
208	      execute_htif_syscall();
209	  }
210	
211	  void handle_htif_32bit_high_write(const std::span<uint8_t>& buf)
212	  {
213	    partial_htif_command |= static_cast<uint64_t>(unpack<uint32_t>(buf)) << 32;
214	    if (++htif_parts_received == HTIF_32BIT_PARTS)
215	      execute_htif_syscall();
216	  }
217	
218	  void dispatch(command_t cmd)
219	  {
220	    uint64_t syscall_args[MAGIC_MEM_SIZE];
221	    auto addr_offset = cmd.payload() - data_region.region.base_address;
222	    auto src = data_region.data.begin() + addr_offset;
223	
224	    std::copy(src, src + sizeof(syscall_args),
225	              reinterpret_cast<uint8_t*>(syscall_args));
226	
227	    spdlog::debug("sim_control: args: {:#x}, {:#x}, {:#x}, "
228	                  "{:#x}, {:#x}, {:#x}, {:#x}",
229	                  syscall_args[0], syscall_args[1], syscall_args[2],
230	                  syscall_args[3], syscall_args[4], syscall_args[5],
231	                  syscall_args[6]);
232	
233	    auto syscall_num = syscall_args[0];
234	    if (syscall_num >= SYSCALL_TABLE_SIZE || !sim_syscall_table[syscall_num]) {
235	      spdlog::critical("sim_control: invalid syscall number {}", syscall_num);
236	      syscall_args[0] = static_cast<uint64_t>(-1);
237	    } else {
238	      syscall_args[0] = (this->*sim_syscall_table[syscall_num])(
239	        syscall_args[1], syscall_args[2], syscall_args[3], syscall_args[4],
240	        syscall_args[5], syscall_args[6], syscall_args[7]);
241	    }
242	
243	    std::copy(reinterpret_cast<uint8_t*>(syscall_args),
244	              reinterpret_cast<uint8_t*>(syscall_args) + sizeof(syscall_args),
245	              src);
246	  }
247	};
