18	template<typename CPU>
19	struct platform_config
20	{
21	  static constexpr size_t data_width = CPU::NDS_BIU_DATA_WIDTH;
22	  static constexpr size_t dmi_addr_width = CPU::dmi_addr_width;
23	  static constexpr size_t dmi_data_width = CPU::dmi_data_width;
24	  static constexpr size_t num_cores = CPU::NDS_NHART;
25	  static constexpr bool has_shared_cache = CPU::has_shared_cache;
26	  static constexpr size_t valen = CPU::NDS_VALEN;
27	};
28	
29	template<typename CONFIG>
30	class Platform : public sc_core::sc_module
31	{
32	public:
33	  static constexpr size_t data_width = CONFIG::data_width;
34	  static constexpr size_t dmi_addr_width = CONFIG::dmi_addr_width;
35	  static constexpr size_t dmi_data_width = CONFIG::dmi_data_width;
36	
37	  ahb::manager<dmi_addr_width, dmi_data_width> dmi{"dmi"};
38	
39	  // CPU signals
40	  sc_core::sc_clock clk{"clk", sc_core::sc_time{1, sc_core::SC_NS}};
41	  sc_core::sc_signal<sc_dt::sc_uint<CONFIG::num_cores>> resetn;
42	  std::array<sc_core::sc_signal<vlpin<CONFIG::valen>>, CONFIG::num_cores>
43	    reset_vector;
44	  sc_core::sc_signal<bool> wfi_signal;
45	  sc_core::sc_signal<sc_dt::sc_uint<31>> int_trigger;
46	
47	  ahb::signals<CONFIG::dmi_addr_width, CONFIG::dmi_data_width> dmi_signals{};
48	
49	  jtag_dtm dtm{"dtm", dmi};
50	
51	  Interconnect<data_width> interconnect{"interconnect"};
52	
53	  SimpleMemory<data_width> main_memory;
54	
55	  SMU<data_width> smu{
56	    "smu", {SMU_BASE, SMU_END}, CONFIG::num_cores, CONFIG::has_shared_cache};
57	
58	  UART<data_width> uart1{"uart1", {UART1_BASE, UART1_END}};
59	  UART<data_width> uart2{"uart2", {UART2_BASE, UART2_END}};
60	
61	  SimControl<data_width> sim_control{"sim_control",
62	                                     {SIM_CONTROL_BASE, SIM_CONTROL_END},
63	                                     main_memory,
64	                                     int_trigger,
65	                                     clk};
66	
67	public:
68	  Platform(const sc_core::sc_module_name& name = "platform",
69	           std::span<uint8_t> ram_buffer = {},
70	           MemoryRegion ram_region = {RAM_BASE, RAM_END},
71	           MemoryRegion ram_alias_region = {RAM_ALIAS_BASE, RAM_ALIAS_END})
72	      : sc_core::sc_module{name},
73	        main_memory("main_memory", ram_region, ram_alias_region, ram_buffer)
74	  {
75	    // default memory mapping, DONT USE these regions
76	    this->interconnect.reserve_region("PLDM", {PLDM_BASE, PLDM_END});
77	
78	    // set up debug module
79	    this->dmi.clk.bind(this->clk);
80	    this->dtm.clk.bind(this->clk);
81	
82	#define X(name) this->dmi.name.bind(this->dmi_signals.name);
83	    EXPAND_AHB_SIGNALS
84	#undef X
85	
86	    // set up main memory
87	    this->interconnect.bind_target(this->main_memory.socket,
88	                                   this->main_memory.region);
89	    this->interconnect.bind_target(this->main_memory.socket,
90	                                   this->main_memory.alias_region);
91	    // bind sim_control
92	    this->interconnect.bind_target(this->sim_control.socket,
93	                                   this->sim_control.region);
94	
95	    // bind SMU
96	    this->interconnect.bind_target(this->smu.socket, this->smu.region);
97	
98	    // bind UARTs
99	    this->interconnect.bind_target(this->uart1.socket, this->uart1.region);
100	    this->interconnect.bind_target(this->uart2.socket, this->uart2.region);
101	  }
102	};
