19	// NOTE: this header is #include'd inside the SimControl class body
20	// (sim_control.hpp), so the functions here are member functions with implicit
21	// `this`. The helpers below are member functions for the same reason -- they
22	// reach `data_region`, which is a private SimControl member.
23	
24	// Convert a guest VA to a host-pointer into data_region.data. Subtracts
25	// region.base_address so the index lands at the correct offset whether the
26	// region starts at 0x0 (Tier-1, no shared mem) or at 0x80000000 (Tier-2,
27	// --shared-mem-base, narrowed RAM). Without this, a guest stack VA like
28	// 0x80700000 indexes 2 GiB into the data span, which is in-bounds for the
29	// 0x90000000-byte owned buffer but OOB for a 128 MiB shared mmap.
30	template<typename T = uint8_t>
31	inline T* guest_va_to_host(uint64_t va)
32	{
33	  const uint64_t off = va - data_region.region.base_address;
34	  return reinterpret_cast<T*>(data_region.data.data() + off);
35	}
36	
37	// Newlib's <sys/_default_fcntl.h> uses BSD-derived O_* values that differ
38	// from the Linux ABI -- e.g. O_CREAT=0x200 in newlib vs 0x40 in Linux,
39	// O_TRUNC=0x400 vs 0x200. Pass-through to host open() with newlib values
40	// would clear O_CREAT/O_EXCL and silently accept O_APPEND, so a fopen("w+")
41	// for a non-existent file fails with ENOENT. Translate flag-by-flag.
42	inline int newlib_to_linux_open_flags(uint64_t newlib_flags)
43	{
44	  constexpr uint64_t NL_RDONLY  = 0;
45	  constexpr uint64_t NL_WRONLY  = 1;
46	  constexpr uint64_t NL_RDWR    = 2;
47	  constexpr uint64_t NL_APPEND  = 0x0008;
48	  constexpr uint64_t NL_CREAT   = 0x0200;
49	  constexpr uint64_t NL_TRUNC   = 0x0400;
50	  constexpr uint64_t NL_EXCL    = 0x0800;
51	  constexpr uint64_t NL_NONBLOCK = 0x4000;
52	  constexpr uint64_t NL_NOCTTY  = 0x8000;
53	
54	  int linux_flags = 0;
55	  switch (newlib_flags & 3) {
56	    case NL_RDONLY: linux_flags |= O_RDONLY; break;
57	    case NL_WRONLY: linux_flags |= O_WRONLY; break;
58	    case NL_RDWR:   linux_flags |= O_RDWR;   break;
59	  }
60	  if (newlib_flags & NL_APPEND)   linux_flags |= O_APPEND;
61	  if (newlib_flags & NL_CREAT)    linux_flags |= O_CREAT;
62	  if (newlib_flags & NL_TRUNC)    linux_flags |= O_TRUNC;
63	  if (newlib_flags & NL_EXCL)     linux_flags |= O_EXCL;
64	  if (newlib_flags & NL_NONBLOCK) linux_flags |= O_NONBLOCK;
65	  if (newlib_flags & NL_NOCTTY)   linux_flags |= O_NOCTTY;
66	  return linux_flags;
67	}
68	
69	uint64_t handle_gettimeofday(uint64_t a0 __attribute__((unused)),
70	                             uint64_t a1 __attribute__((unused)),
71	                             uint64_t a2 __attribute__((unused)),
72	                             uint64_t a3 __attribute__((unused)),
73	                             uint64_t a4 __attribute__((unused)),
74	                             uint64_t a5 __attribute__((unused)),
75	                             uint64_t a6 __attribute__((unused)))
76	{
77	  struct timeval tv;
78	  struct timezone tz;
79	  int ret = gettimeofday(&tv, &tz);
80	  if (ret == -1) {
81	    spdlog::error("sys_call: gettimeofday failed: {}", std::strerror(errno));
82	    return -1;
83	  }
84	
85	  void* target_tv = guest_va_to_host<void>(a0);
86	
87	  if (riscv_xlen == 32) {
88	    ((struct timeval_32*) target_tv)->tv_sec = (uint32_t) tv.tv_sec;
89	    ((struct timeval_32*) target_tv)->tv_usec = (uint32_t) tv.tv_usec;
90	  } else {
91	    ((struct timeval_64*) target_tv)->tv_sec = tv.tv_sec;
92	    ((struct timeval_64*) target_tv)->tv_usec = tv.tv_usec;
93	  }
94	
95	  return 0;
96	};
97	
98	uint64_t handle_open(uint64_t a0 __attribute__((unused)),
99	                     uint64_t a1 __attribute__((unused)),
100	                     uint64_t a2 __attribute__((unused)),
101	                     uint64_t a3 __attribute__((unused)),
102	                     uint64_t a4 __attribute__((unused)),
103	                     uint64_t a5 __attribute__((unused)),
104	                     uint64_t a6 __attribute__((unused)))
105	{
106	  const char* name = guest_va_to_host<const char>(a0);
107	  const int linux_flags = newlib_to_linux_open_flags(a1);
