#pragma once

#include "memory_region.hpp"

#include <spdlog/spdlog.h>
#include <systemc>
#include <tlm>
#include <tlm_utils/simple_target_socket.h>

#include <cstdint>
#include <span>
#include <vector>

template<std::size_t BusWidth>
class SimpleMemory : public sc_core::sc_module
{
public:
  static constexpr uint64_t INVALID_ADDRESS = 0xffffffffffffffff;

  const MemoryRegion region;
  const MemoryRegion alias_region;

private:
  std::vector<uint8_t> owned_storage_;

public:
  std::span<uint8_t> data;

  unsigned latency = 1;
  tlm_utils::simple_target_socket<SimpleMemory<BusWidth>, BusWidth> socket{
    "tsck"};

  // If `external_buffer` is empty, owned storage of region size is allocated.
  // Otherwise the buffer must outlive this object and be at least region size;
  // the size mismatch is rejected before any allocation.
  SimpleMemory(const sc_core::sc_module_name& name,
               const MemoryRegion& region,
               const MemoryRegion& alias_region = {INVALID_ADDRESS,
                                                   INVALID_ADDRESS},
               std::span<uint8_t> external_buffer = {})
      : sc_core::sc_module{name},
        region(region),
        alias_region(alias_region),
        owned_storage_(owned_size(external_buffer, region)),
        data(external_buffer.empty() ? std::span<uint8_t>{owned_storage_}
                                     : external_buffer)
  {
    this->socket.register_b_transport(this, &SimpleMemory::b_transport);
  }

  void b_transport(tlm::tlm_generic_payload& trans, sc_core::sc_time& delay)
  {
    auto cycles = handle_trans(trans);
    if (trans.get_response_status() == tlm::TLM_INCOMPLETE_RESPONSE)
      trans.set_response_status(tlm::TLM_OK_RESPONSE);
    delay += sc_core::sc_time(cycles, sc_core::SC_NS);
  }

private:
  static auto owned_size(std::span<uint8_t> external_buffer,
                         const MemoryRegion& region) -> std::size_t
  {
    const auto required = region.end_address - region.base_address;
    if (external_buffer.empty())
      return required;
    if (external_buffer.size() < required) [[unlikely]]
      throw std::runtime_error(
        "SimpleMemory external_buffer smaller than region size");
    return 0;
  }

  auto handle_trans(tlm::tlm_generic_payload& trans) -> unsigned
  {
    const auto addr = trans.get_address();
    const auto len = trans.get_data_length();
    const auto ptr = trans.get_data_ptr();
    const auto byte_enable_len = trans.get_byte_enable_length();
    const auto byte_enable_ptr = trans.get_byte_enable_ptr();

    spdlog::debug("mem: {}, addr={:#x}, len={}",
                  trans.is_read() ? "read" : "write", addr, len);

    uint64_t offset;
    if (region.contains_access(addr, len)) [[likely]] {
      offset = addr - this->region.base_address;
    } else if (alias_region.contains_access(addr, len)) {
      offset = addr - this->alias_region.base_address;
    } else {
      spdlog::error(
        "transaction is out of bounds of memory region [{:#x}-{:#x}]",
        this->region.base_address, this->region.end_address);
      trans.set_response_status(tlm::TLM_ADDRESS_ERROR_RESPONSE);
      return latency;
    }
    const auto buf = std::span{ptr, ptr + len};
    if (trans.is_read()) [[likely]] {
      std::copy_n(this->data.begin() + offset, len, buf.begin());
      return latency;
    }

    if (!trans.is_write()) [[unlikely]] {
      throw std::runtime_error("unimplemented");
    }

    if (byte_enable_len == 0) [[likely]] {
      std::copy_n(buf.begin(), len, this->data.begin() + offset);
      return latency;
    }

    // AXI/AHB may split an un-aligned write into multiple aligned writes
    // with a byte-enable mask.
    assert(byte_enable_len == len);
    for (unsigned i = 0; i < len; i++) {
      if (byte_enable_ptr[i] == 0xff)
        this->data[offset + i] = buf[i];
    }
    return latency;
  }
};

#pragma once

#include <cstdint>

#include <format>
#include <limits>
#include <stdexcept>
#include <string>
#include <string_view>

/**
 * A memory region in the range of `[base_address, end_address)`.
 * The constructor takes an inclusive end address and stores it as exclusive.
 * e.g. memory_region(0x80000000, 0x8fffffff) stores base=0x80000000,
 *      end=0x90000000.
 */
struct MemoryRegion
{
  using addr_type = uint64_t;

  const addr_type base_address; // inclusive
  const addr_type end_address; // exclusive (stored as param + 1)

  /**
   * @param base_address The base address of the memory region (inclusive).
   * @param end_address The end address of the memory region (inclusive).
   * @throws std::invalid_argument if base_address > end_address.
   * @example memory_region(0x00, 0xff) represents [0x00, 0x100)
   */
  MemoryRegion(const addr_type base_address, const addr_type end_address)
      : base_address{base_address}, end_address{end_address + 1}
  {
    if (base_address > end_address)
      throw std::invalid_argument(std::format(
        "invalid memory region: [{:#x}-{:#x}]", base_address, end_address));
  }

  auto contains(const addr_type addr) const noexcept -> bool
  {
    return addr >= this->base_address && addr < this->end_address;
  }

  auto contains(const MemoryRegion& other) const noexcept -> bool
  {
    return other.base_address >= this->base_address
        && other.end_address <= this->end_address;
  }

  // Does this region fully contain the half-open access [addr, addr + len)?
  // Takes a raw access (exclusive length) rather than a MemoryRegion, so it
  // does NOT go through the inclusive-end ctor (which adds 1). An access whose
  // exclusive end lands exactly on end_address is contained, so the final byte
  // of the region is reachable. contains(addr) also guarantees addr <
  // end_address, so end_address - addr cannot underflow, and comparing len
  // against it avoids overflowing addr + len at the top of the address space.
  auto contains_access(const addr_type addr,
                       const addr_type len) const noexcept -> bool
  {
    return this->contains(addr) && len <= this->end_address - addr;
  }

  auto overlaps(const MemoryRegion& other) const noexcept -> bool
  {
    return this->end_address > other.base_address
        && this->base_address < other.end_address;
  }
};

/**
 * The CPU HVM subordinate-port aperture. NDS_HVM_SIZE_KB is KILOBYTES; the
 * decode window must equal the memory, so the KB conversion lives here, in
 * one named place (a *0x1000 at the bind sites once decoded a 4x window).
 */
inline auto hvm_aperture(const MemoryRegion::addr_type base,
                         const MemoryRegion::addr_type size_kb) -> MemoryRegion
{
  return {base, base + size_kb * 1024 - 1};
}

/**
 * One `--print-memmap` line. Converts the stored EXCLUSIVE end back to the
 * inclusive last byte and the true span here, in one place, so no dump site
 * re-does the arithmetic (a former dump printed the exclusive end as if
 * inclusive and size = span + 1). Reserved holes -- regions blocked from
 * binding, not routable targets -- are tagged.
 */
inline auto format_region_line(const std::string_view name,
                               const MemoryRegion& mr,
                               const bool reserved = false) -> std::string
{
  return std::format("{}: [{:#x}-{:#x}] (size: {:#x}){}", name,
                     mr.base_address, mr.end_address - 1,
                     mr.end_address - mr.base_address,
                     reserved ? " (reserved)" : "");
}

