52	    case Kind::CmdErr:        return "cmderr";
53	  }
54	  return "?";
55	}
56	
57	inline void log_hybrid_ops(const char* phase, const hybrid::OpLog& log)
58	{
59	  using Kind = hybrid::OpLog::Kind;
60	  std::size_t gpr = 0, fpr = 0, csr = 0, reads = 0, pb = 0, fb = 0, err = 0;
61	  for (const auto& e : log.events) {
62	    switch (e.kind) {
63	      case Kind::AbstractWrite:
64	        // Abstract regno classes: 0x1000+ GPR, 0x1020+ FPR, else CSR.
65	        if (e.regno >= 0x1020) ++fpr;
66	        else if (e.regno >= 0x1000) ++gpr;
67	        else ++csr;
68	        break;
69	      case Kind::AbstractRead: ++reads; break;
70	      case Kind::ProgBuf:      ++pb;    break;
71	      case Kind::PbFallback:   ++fb;    break;
72	      case Kind::CmdErr:       ++err;   break;
73	    }
74	  }
75	  spdlog::debug("hybrid: {} ops: {} gpr / {} fpr / {} csr abstract writes, "
76	                "{} abstract reads, {} progbuf execs, {} pb fallbacks, "
77	                "{} cmderr",
78	                phase, gpr, fpr, csr, reads, pb, fb, err);
79	  for (const auto& e : log.events)
80	    if (e.kind == Kind::CmdErr)
81	      spdlog::debug("hybrid: {}: cmderr={} on regno=0x{:x} (tolerated)",
82	                    phase, e.value, e.regno);
83	  if (!spdlog::should_log(spdlog::level::trace)) return;
84	  for (const auto& e : log.events)
85	    spdlog::trace("hybrid: {}: {} regno=0x{:x} value=0x{:x}",
86	                  phase, hybrid_op_kind_name(e.kind), e.regno, e.value);
87	}
