89	// V3: on a resume abort the tail of the op log IS the forensic trail -- it
90	// names the register/CSR the transport was touching when it died.
91	inline void log_hybrid_abort_tail(const hybrid::OpLog& log)
92	{
93	  const std::size_t n = log.events.size();
94	  spdlog::error("hybrid: resume aborted after {} transport ops; last ops:", n);
95	  const std::size_t from = n > 8 ? n - 8 : 0;
96	  for (std::size_t i = from; i < n; ++i) {
97	    const auto& e = log.events[i];
98	    spdlog::error("hybrid:   [{}] {} regno=0x{:x} value=0x{:x}",
99	                  i, hybrid_op_kind_name(e.kind), e.regno, e.value);
100	  }
101	  spdlog::error("hybrid: re-run with --log-level 0 for the full per-op trace");
102	}
