104	// Local-memory backdoor capabilities of a cpu wrapper -- the ONE authority
105	// for "can this engine load/dump ILM/DLM content" (LM transport,
106	// ROADMAP_ilm_dlm). load_image, dump_lm_sidecars, and main's describe gate
107	// all read these, so the advertise side and the load/dump sides cannot
108	// drift. Variable templates so the requires-expressions sit in a DEPENDENT
109	// context: a wrapper without the member SFINAEs to false, where the same
110	// expression written non-dependently is a hard compile error.
111	template <typename CPU>
112	inline constexpr bool kCpuCanLoadIlm = requires(CPU& c) { c.set_ilm({}); };
113	template <typename CPU>
114	inline constexpr bool kCpuCanLoadDlm = requires(CPU& c) { c.set_dlm({}); };
115	template <typename CPU>
116	inline constexpr bool kCpuCanDumpIlm = requires(CPU& c) { c.get_ilm(); };
117	template <typename CPU>
118	inline constexpr bool kCpuCanDumpDlm = requires(CPU& c) { c.get_dlm(); };
119	// Same authority pattern for the HVM backdoor (HVM transport, ROADMAP_hvm).
120	template <typename CPU>
121	inline constexpr bool kCpuCanLoadHvm = requires(CPU& c) { c.set_hvm({}); };
122	template <typename CPU>
123	inline constexpr bool kCpuCanDumpHvm = requires(CPU& c) { c.get_hvm(); };
