275	  void init_debug_port(const uint16_t port = 9104)
276	  {
277	    dtm_debug = true;
278	    dtm.init_port(port);
279	    spdlog::info("waiting for debugger connection");
280	  }
281	
282	  // Caller invariant: the CPU must already be out of reset.
283	  //
284	  // baseline_cache (LG3): path to this (engine build, ELF)'s reset-state
285	  // baseline; empty disables the liveness gate (transport-everything). On a
286	  // cache miss the baseline is captured HERE: the hart is freshly reset and
287	  // the capture drain halts it exactly where resume() would, so the drained
288	  // values ARE what the gate must compare restores against. Capture runs
289	  // BEFORE the scratch stagings below -- its drain sweeps dump reset
290	  // registers through the same scratch page the stagings fill.
291	  void apply_resume_from_qemu(const std::string& path,
292	                              const std::string& baseline_cache = {})
293	  {
294	    hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width, PLATFORM::dmi_data_width>
295	      bus{platform.dmi, platform.clk.period()};
296	    hybrid_input_state_ = hybrid::load_state(path);
297	
298	    std::optional<hybrid_state_v1> baseline{};
299	    bool baseline_captured = false;
300	    if (!baseline_cache.empty()) {
301	      baseline = hybrid::try_load_reset_baseline(baseline_cache);
302	      // Stale-shape insurance: a cache whose flags/vlenb no longer cover the
303	      // incoming state was captured under a different engine/QEMU pairing.
304	      if (baseline
305	          && ((baseline->flags & hybrid_input_state_->flags)
306	                != hybrid_input_state_->flags
307	              || baseline->vlenb != hybrid_input_state_->vlenb))
308	        baseline.reset();
309	      if (!baseline) {
310	        baseline = capture_reset_baseline(bus, *hybrid_input_state_);
311	        baseline_captured = true;
312	        if (!hybrid::save_reset_baseline(baseline_cache, *baseline))
313	          spdlog::warn("hybrid: cannot save reset baseline to {}",
314	                       baseline_cache);
315	      }
316	      spdlog::info("hybrid: reset baseline {} ({})",
317	                   baseline_captured
318	                     ? "captured -- one-time cost per engine build + ELF"
319	                     : "cache hit",
320	                   baseline_cache);
321	    }
322	
323	    // Stage V-register bytes into the fixed scratch region of RAM BEFORE
324	    // resume: ResumeDriver's Program-Buffer reload sweep issues vle8.v from
325	    // this region to repopulate v0..v31, so the bytes must be in place first.
326	    // Best-effort: mismatched RAM layouts throw, which is louder than silently
327	    // dropping V state.
328	    if ((hybrid_input_state_->flags & HYBRID_FLAG_V) != 0u) {
329	      hybrid::stage_v_to_scratch(*hybrid_input_state_,
330	                                 platform.main_memory.data);
331	    }
332	    // GPR/FPR/CSR transport is Abstract-Command-only in BOTH directions (never
333	    // Program Buffer): a csrrw to a caps-supported but read-only / WARL-illegal
334	    // CSR raises cmderr, and the abstract path's per-CSR clear_cmderr tolerates
335	    // that single failure and moves on -- a batched PB sweep could not. The
336	    // Program Buffer carries only what abstract commands cannot reach: the V
337	    // data sweep, the Tier-B vsetvl, and the L2C MMIO window.
338	    const auto caps = active_caps();
339	    hybrid::ResumeDriver driver(bus, v_scratch_gpa(), caps);
340	    driver.set_l2c(l2c_present(), l2c_base());  // v5: restore L2C config if present
341	    // LG3: on a capture run the capture drain's V dump sweep clobbered
342	    // vtype/vl/vstart, so the vsetvl elision is only valid on cache hits.
343	    if (baseline)
344	      driver.set_reset_baseline(*baseline,
345	                                /*v_cfg_at_reset=*/!baseline_captured);
346	    std::size_t andes_mext_csrs = 0;
347	    hybrid::for_each_transport_csr(*hybrid_input_state_, caps,
348	      [&](uint16_t, const uint64_t&) { ++andes_mext_csrs; });
349	    // V1/V2: record the transport ops when debug is on; V3: on an abort the
350	    // op-log tail names the register/CSR the restore died on.
351	    hybrid::OpLog oplog;
352	    const bool log_ops = spdlog::should_log(spdlog::level::debug);
353	    if (log_ops) driver.set_op_log(&oplog);
354	    const auto resume_t0 = sc_core::sc_time_stamp();
355	    const auto wall_t0 = std::chrono::steady_clock::now();
356	    try {
357	      driver.resume(*hybrid_input_state_);
358	    } catch (const std::exception&) {
359	      if (log_ops) log_hybrid_abort_tail(oplog);
360	      throw;
361	    }
362	    const auto wall_ms = std::chrono::duration_cast<std::chrono::milliseconds>(
363	      std::chrono::steady_clock::now() - wall_t0).count();
364	    const auto resume_cycles = static_cast<uint64_t>(
365	      (sc_core::sc_time_stamp() - resume_t0) / platform.clk.period());
366	    spdlog::info("hybrid: resume={} cycles ({} ms wall), restore path="
367	                 "abstract, andes+m-ext csrs={}",
368	                 resume_cycles, wall_ms, andes_mext_csrs);
369	    if (baseline)
370	      spdlog::info("hybrid: liveness gate elided {} register restores",
371	                   driver.baseline_skip_count());
372	    if (log_ops) log_hybrid_ops("resume", oplog);
373	  }
374	
375	  // F3: standalone CSR existence + reset-value probe. Halts the freshly-reset
376	  // hart via DMI and checked-reads each address -- cmderr (an unimplemented
377	  // CSR) surfaces as nullopt. No QEMU state, no run(): the read values ARE the
378	  // architectural reset state. Emitted by `--probe`, consumed by andesim's
379	  // gen_manifest.py to MEASURE the implemented set + reset values instead of
380	  // hand-tracing RTL params. The caller must load a (spin) ELF first so the
381	  // reset vector is mapped -- the hart fetches a couple instructions from it
382	  // before the DMI halt takes effect (same window capture_reset_baseline uses).
383	  auto probe_csrs(const std::vector<uint16_t>& addrs)
384	    -> std::vector<std::pair<uint16_t, std::optional<uint64_t>>>
385	  {
386	    using RD = hybrid::ResumeDriver;
387	    hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width, PLATFORM::dmi_data_width>
388	      bus{platform.dmi, platform.clk.period()};
389	    bus.write(RD::kDmcontrol, RD::kDmcontrolDmactive);
390	    bus.write(RD::kDmcontrol, RD::kDmcontrolDmactive | RD::kDmcontrolHaltreq);
391	    hybrid::poll_until_set(bus, RD::kDmstatus, RD::kDmstatusAllhalted,
392	                           "csr-probe halt");
393	    // At reset mstatus.FS/VS are Off, so FP/V CSR reads raise illegal-insn
394	    // (cmderr) and would mis-probe as absent. Enable them (WARL no-op on an
395	    // engine without FP/V), exactly like capture_reset_baseline before its
396	    // FP/V reads. mstatus's own probed value is thus FS/VS-perturbed -- a known
397	    // artifact (mstatus is a base always-transported, verify-excluded CSR).
398	    {
399	      const uint64_t mstatus = hybrid::read_register_64(
400	        bus, hybrid::regno_csr(RD::kCsrMstatus), "csr-probe mstatus");
401	      uint64_t enable = mstatus;
402	      if ((enable & RD::kMstatusFsMask) == 0) enable |= RD::kMstatusFsInitial;
403	      if ((enable & RD::kMstatusVsMask) == 0) enable |= RD::kMstatusVsInitial;
404	      if (enable != mstatus)
405	        hybrid::write_register_abstract(
406	          bus, hybrid::regno_csr(RD::kCsrMstatus), enable);
407	    }
408	    std::vector<std::pair<uint16_t, std::optional<uint64_t>>> out;
409	    out.reserve(addrs.size());
410	    for (const uint16_t a: addrs)
411	      out.emplace_back(a, hybrid::read_register_64_checked(
412	                            bus, hybrid::regno_csr(a), "csr-probe"));
413	    return out;
414	  }
415	
416	  // Enables the vsim->QEMU handoff drain. After this is set, run() watches
417	  // committed PCs and on retire of the `slti x0, x0, 0x5A1` exit marker drains
418	  // architectural state to `state_out_path` and returns kExitHandoffToQemu.
419	  //
420	  // When `exit_pc` is set, the trigger is populated by `add_pc_hit` (PC
421	  // mode) and the ELF scan is skipped: the binary need not contain a marker
422	  // HINT. Marker mode and PC mode are mutually exclusive on a single run --
423	  // callers pass exactly one form.
424	  void enable_hybrid_handoff(const std::string& elf_path,
425	                             const std::string& state_out_path,
426	                             std::optional<uint64_t> exit_pc = std::nullopt,
427	                             bool drain_minimal = false)
428	  {
429	    hybrid::CsrTrigger trigger;
430	    if (exit_pc) {
431	      trigger.add_pc_hit(*exit_pc, HYBRID_HANDOFF_EXIT);
432	      spdlog::info("hybrid: PC-trigger mode, exit_pc=0x{:x}", *exit_pc);
433	    } else {
434	      auto elf = LIEF::ELF::Parser::parse(elf_path);
435	      if (!elf)
436	        throw std::runtime_error(
437	          "enable_hybrid_handoff: failed to parse " + elf_path);
438	      for (const auto& seg: elf->segments()) {
439	        if (seg.type() != LIEF::ELF::SEGMENT_TYPES::PT_LOAD) continue;
440	        if ((static_cast<unsigned>(seg.flags()) & 1u) == 0u) continue;  // PF_X
441	        const auto content = seg.content();
442	        const std::span<const uint8_t> bytes{content.data(), content.size()};
443	        trigger.scan_buffer(bytes, seg.virtual_address());
444	      }
445	    }
446	
447	    hybrid_dmi_bus_ = std::make_unique<
448	      hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width,
449	                            PLATFORM::dmi_data_width>>(platform.dmi,
450	                                                       platform.clk.period());
451	    hybrid_handoff_.emplace(std::move(trigger), *hybrid_dmi_bus_,
452	                            v_scratch_gpa(), active_caps());
453	    if (hybrid_input_state_)
454	      hybrid_handoff_->set_passthrough_input(*hybrid_input_state_);
455	    hybrid_handoff_->set_minimal_drain(drain_minimal);
456	    hybrid_handoff_->set_l2c(l2c_present(), l2c_base());  // v5: exit drain re-reads L2C
457	    // V2: record the exit drain's ops when debug is on (rendered at the
458	    // drain site in check_hybrid_handoff).
459	    if (spdlog::should_log(spdlog::level::debug))
460	      hybrid_handoff_->set_op_log(&hybrid_drain_oplog_);
461	
462	    hybrid_state_path_ = state_out_path;
463	  }
464	
465	  // F6: override the config-derived caps with a manifest-driven transport set
466	  // (from --transport-csrs). When set, active_caps() returns this instead of
467	  // andes_caps_from_config() -- the runtime transport is then driven by the
468	  // registered manifest, not by re-modelling config macros.
469	  void set_transport_caps(const hybrid::AndesCaps& c) { transport_caps_ = c; }
470	
471	private:
472	  std::optional<hybrid::AndesCaps> transport_caps_{};
473	  auto active_caps() const -> hybrid::AndesCaps
474	  {
475	    return transport_caps_ ? *transport_caps_ : hybrid::andes_caps_from_config();
476	  }
477	
478	  // v5: L2C MMIO transport gate, derived from the build's Verilog config macros
479	  // (_NDS_*, supplied via cpu_config.hpp -- same source as andes_caps_from_
480	  // config). Present only when this engine is built with an L2 cache controller
481	  // AND its register base is known. Gated on _NDS_L2C_CACHE_SIZE_KB, not the
482	  // cluster's has_shared_cache, because that flag also covers L3 (ax46/ax66).
483	  // A store to an absent L2C region would fault the Program Buffer, so this
484	  // stays off on every current engine (_NDS_L2C_CACHE_SIZE_KB == 0).
485	  static constexpr bool l2c_present()
486	  {
487	#if defined(_NDS_L2C_CACHE_SIZE_KB) && defined(_NDS_L2C_REG_BASE)
488	    return (_NDS_L2C_CACHE_SIZE_KB) > 0;
489	#else
490	    return false;
491	#endif
492	  }
493	  static constexpr uint64_t l2c_base()
494	  {
495	#if defined(_NDS_L2C_REG_BASE)
496	    return static_cast<uint64_t>(_NDS_L2C_REG_BASE);
497	#else
498	    return 0;
499	#endif
500	  }
501	
502	  // L26: the GUEST address of the V-register transport page -- the top page of
503	  // the mapped RAM span. The driver maps one page above --mem-size (scheme D),
504	  // so this sits just past the program's declared RAM and never collides with
505	  // its data/stack. Single source of truth handed to ResumeDriver/StateDrain.
506	  auto v_scratch_gpa() const -> uint64_t
507	  {
508	    return hybrid::v_scratch_gpa(platform.main_memory.region.base_address,
509	                                 platform.main_memory.data.size());
510	  }
511	
512	  // LG3: drain the freshly reset, just-halted hart into a baseline the
513	  // liveness gate compares restores against. The probe carries the incoming
514	  // state's flags/vlenb so drain_with_passthrough reads exactly the blocks
515	  // the gate will compare (it is flag-driven); every probe field it does not
516	  // re-read stays zero, matching what an absent block compares against.
517	  auto capture_reset_baseline(
518	    hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width,
519	                          PLATFORM::dmi_data_width>& bus,
520	    const hybrid_state_v1& input) -> hybrid_state_v1
521	  {
522	    hybrid::StateDrain drain(bus, v_scratch_gpa(),
523	                             active_caps());
524	    // At reset mstatus.FS/VS are Off, so the capture's vse8 sweep (and the
525	    // FPR/V CSR abstract reads) would raise illegal instruction (cmderr=3).
526	    // Halt and enable them first, exactly like resume() does before its FPR/V
527	    // writes. Safe to clobber: mstatus is never re-read by a drain nor gated
528	    // by the baseline, and resume() rewrites it whenever the FP/V flags are
529	    // set -- the only case this branch runs.
530	    if (input.flags & (HYBRID_FLAG_FP | HYBRID_FLAG_V)) {
531	      using RD = hybrid::ResumeDriver;
532	      bus.write(RD::kDmcontrol, RD::kDmcontrolDmactive);
533	      bus.write(RD::kDmcontrol,
534	                RD::kDmcontrolDmactive | RD::kDmcontrolHaltreq);
535	      hybrid::poll_until_set(bus, RD::kDmstatus, RD::kDmstatusAllhalted,
536	                             "reset-baseline capture halt");
537	      const uint64_t mstatus = hybrid::read_register_64(
538	        bus, hybrid::regno_csr(RD::kCsrMstatus), "reset-baseline mstatus");
539	      uint64_t enable = mstatus;
540	      if ((input.flags & HYBRID_FLAG_FP)
541	          && (enable & RD::kMstatusFsMask) == 0)
542	        enable |= RD::kMstatusFsInitial;
543	      if ((input.flags & HYBRID_FLAG_V)
544	          && (enable & RD::kMstatusVsMask) == 0)
545	        enable |= RD::kMstatusVsInitial;
546	      if (enable != mstatus)
547	        hybrid::write_register_abstract(
548	          bus, hybrid::regno_csr(RD::kCsrMstatus), enable);
549	    }
550	    hybrid_state_v1 probe{};
551	    probe.magic = HYBRID_STATE_MAGIC;
552	    probe.version = HYBRID_STATE_VERSION;
553	    probe.flags = input.flags;
554	    probe.vlenb = input.vlenb;
555	    auto baseline = drain.drain_with_passthrough(probe);
556	    lift_scratch_blocks(baseline);
557	    return baseline;
558	  }
559	
560	  // Lift the scratch-page transport into `state` (dual of the resume
561	  // staging): the V dump sweep bytes back into state.vreg[] -- so the drained
562	  // state carries vsim's actual V values, not QEMU 1's stale snapshot. The V
563	  // regfile is the only state that rides the scratch page; GPRs, FPRs, and
564	  // every CSR drain via abstract reads directly into the state. Shared by the
565	  // exit drain and the reset-baseline capture.
566	  void lift_scratch_blocks(hybrid_state_v1& state)
567	  {
568	    const std::span<const uint8_t> ram{platform.main_memory.data.data(),
569	                                       platform.main_memory.data.size()};
570	    if ((state.flags & HYBRID_FLAG_V) != 0u)
571	      hybrid::read_v_from_scratch(state, ram);
572	  }
573	
574	public:
575	
576	  void restore_context(const std::string& dir)
577	  {
578	    context_config.dir = dir;
579	    context_config.restore(platform, cpu);
580	  }
581	
582	  // skip_memory_load: parse the ELF and set the reset vector, but leave
583	  // platform.main_memory untouched. Used in tier-2 hybrid resume where
584	  // QEMU 1's -kernel already populated the shared mmap; re-loading would
585	  // zero-fill the .bss tail of each PT_LOAD and destroy phase-1 writes
586	  // to static buffers. The reset vector is still set so the hart has a
587	  // valid fetch target during the post-reset cycles that precede the DMI
588	  // halt+DPC-write resume sequence.
589	  void load_elf(const std::string& path, bool skip_memory_load = false)
590	  {
591	    const auto elf = LIEF::ELF::Parser::parse(path);
592	    if (!elf) {
593	      spdlog::critical("Check if it's a valid ELF file path : {}", path);
594	      exit(1);
595	    }
596	
597	    if (!skip_memory_load)
598	      read_elf_into_memory(
599	        *elf,
600	        static_cast<xlen_t>(platform.main_memory.region.base_address),
601	        platform.main_memory.data);
602	    for (auto& rv: platform.reset_vector)
603	      rv.write(elf->entrypoint());
604	  }
605	
606	  void set_reset_vector(size_t hart, uint64_t addr)
607	  {
608	    if (hart >= platform.reset_vector.size()) {
609	      spdlog::critical("hart {} out of range (max {})", hart,
610	                       platform.reset_vector.size() - 1);
611	      std::exit(EXIT_FAILURE);
612	    }
613	    platform.reset_vector[hart].write(addr);
614	  }
615	
616	  // F5 (ROADMAP_ilm_dlm) + F4 (ROADMAP_hvm): dump the local memories' and
617	  // HVM's content next to the handoff-out state file -- the read duals of
618	  // the --ilm/--dlm/--hvm backdoor load, same "<state>.ilm/.dlm/.hvm"
619	  // sidecar convention as the QEMU plugin's entry drain. Zero sim cycles
620	  // (hierarchical-reference read, ECC stripped). A wrapper without the
621	  // get_* dumps nothing. Called by check_hybrid_handoff right after the
622	  // state-file write, so the "state file plus sidecars ride together"
623	  // contract has a single producer.
624	  void dump_lm_sidecars(const std::string& state_path)
625	  {
626	    auto dump = [](const std::string& path, const std::vector<uint8_t>& data) {
627	      std::ofstream f(path, std::ios::binary | std::ios::trunc);
628	      f.write(reinterpret_cast<const char*>(data.data()),
629	              static_cast<std::streamsize>(data.size()));
630	      if (!f) throw std::runtime_error("cannot write " + path);
631	    };
632	    if constexpr (kCpuCanDumpIlm<CPU>)
633	      dump(state_path + ".ilm", cpu.get_ilm());
634	    if constexpr (kCpuCanDumpDlm<CPU>)
635	      dump(state_path + ".dlm", cpu.get_dlm());
636	    if constexpr (kCpuCanDumpHvm<CPU>)
637	      dump(state_path + ".hvm", cpu.get_hvm());
638	  }
639	
640	  void load_image(const std::string& path, MEM_TYPE type)
641	  {
642	    switch (type) {
643	    case MEM_TYPE::ILM:
644	      if constexpr (kCpuCanLoadIlm<CPU>) {
645	        read_binary_file(path, [this](const auto& data) { cpu.set_ilm(data); });
646	      } else {
647	        throw std::runtime_error(
648	          "CPU does not support ILM - cannot load ILM ROM image");
649	      }
650	      break;
651	
652	    case MEM_TYPE::DLM:
653	      if constexpr (kCpuCanLoadDlm<CPU>) {
654	        read_binary_file(path, [this](const auto& data) { cpu.set_dlm(data); });
655	      } else {
656	        throw std::runtime_error(
657	          "CPU does not support DLM - cannot load DLM ROM image");
658	      }
659	      break;
660	
661	    case MEM_TYPE::HVM:
662	      if constexpr (kCpuCanLoadHvm<CPU>) {
663	        read_binary_file(path, [this](const auto& data) { cpu.set_hvm(data); });
664	      } else {
665	        throw std::runtime_error(
666	          "CPU does not support HVM - cannot load HVM image");
667	      }
668	      break;
669	
670	    case MEM_TYPE::RAM:
671	      read_binary_file(path, [this](const auto& data) {
672	        if (data.size() > platform.main_memory.data.size())
673	          throw std::runtime_error("RAM image size exceeds main memory size");
674	        std::copy(data.begin(), data.end(), platform.main_memory.data.begin());
675	      });
676	      break;
677	
678	    default:
679	      throw std::runtime_error("Unknown memory type");
680	    }
681	  }
682	
683	  void reset()
684	  {
685	    static constexpr int core_num = CPU::NDS_NHART;
686	    static constexpr int reset_val = (1 << core_num) - 1;
687	
688	    platform.resetn.write(0);
689	    auto saved = context_config;
690	    context_config = {};
691	    this->run(1);
692	    context_config = saved;
693	
694	    for (size_t i = 0; i < platform.reset_vector.size(); ++i)
695	      spdlog::info("hart {} reset vector: {:#x}", i,
696	                   (uint64_t) platform.reset_vector[i].read());
697	
698	    platform.resetn.write(reset_val);
699	
700	    if (context_config.continue_from)
701	      restore_context(context_config.dir);
702	  }
703	
704	  int run(const uint64_t max_cycles = std::numeric_limits<uint64_t>::max())
705	  {
706	    auto sa = memzeroed<struct sigaction>();
707	    sa.sa_handler = sigint_handler;
708	    sigemptyset(&sa.sa_mask);
709	
710	    auto oact = memzeroed<struct sigaction>();
711	    if (sigaction(SIGINT, &sa, &oact) == -1)
712	      perror("sigaction");
713	
714	    const auto restore_sigint = std::experimental::scope_exit{[&] {
715	      if (sigaction(SIGINT, &oact, nullptr) == -1)
716	        perror("sigaction");
717	    }};
718	
719	    // wait for debugger connections
720	    while (dtm_debug && !dtm.is_connected()) {
721	      dtm.try_accept_socket();
722	      if (ctrlc != 0) {
723	        return 130;
724	      }
725	      sleep(1);
726	    }
727	
728	    [[maybe_unused]]
729	    bool ctx_resuming = context_config.continue_from;
730	    [[maybe_unused]]
731	    bool ctx_triggered = false;
732	
733	    for (auto n = uint64_t{0}; n < max_cycles; ++n) {
734	
735	      if (ctx_resuming) [[unlikely]] {
736	        // Pull up PLIC interrupt signal at the first cycle of the resume
737	        platform.int_trigger.write(1);
738	        ctx_resuming = false;
739	        ctx_triggered = true;
740	      }
741	
742	      sc_core::sc_start(platform.clk.period());
743	
744	      trace_.on_cycle(cpu);
745	
746	      if (hybrid_handoff_) [[unlikely]] {
747	        if (auto code = check_hybrid_handoff(); code) return *code;
748	      }
749	
750	      if (context_config.save_on_wfi && platform.wfi_signal.read() == true)
751	        [[unlikely]]
752	      {
753	        context_config.save(platform, cpu);
754	        spdlog::info("User save context");
755	        return 0;
756	      }
757	
758	      if (ctrlc != 0) {
759	        ctrlc = 0;
760	        spdlog::info("Ctrl+C PC: {:x}", get_current_pc());
761	        trace_.log_committed_pcs(cpu);
762	        return 130;
763	      }
764	
765	      if (ctx_triggered) [[unlikely]] {
766	        // Pull down the interrupt signal after 1 cycle
767	        platform.int_trigger.write(0);
768	        ctx_triggered = false;
769	      }
770	
771	      if (platform.sim_control.exits >= 0) {
772	        spdlog::info("sim_control: got exit {}, stopping",
773	                     platform.sim_control.exits);
774	        spdlog::info("Exit PC: {:x}", get_current_pc());
775	        trace_.log_committed_pcs(cpu);
776	        return platform.sim_control.exits;
777	      }
778	
779	      if (this->cpu.contextp()->gotFinish())
780	        return 0;
781	
782	      spdlog::trace("PC: {:x}", get_current_pc());
783	    }
784	    return 0;
785	  }
786	
787	  uint64_t get_current_pc()
788	  {
789	    if constexpr (requires { cpu.get_current_pc(); }) {
790	      return cpu.get_current_pc();
791	    }
792	    return std::numeric_limits<uint64_t>::max();
793	  }
794	
795	  auto check_hybrid_handoff() -> std::optional<int>
796	  {
797	    if constexpr (!requires { cpu.get_committed_pc(); }) {
798	      return std::nullopt;
799	    } else {
800	      const auto committed = cpu.get_committed_pc();
801	      if (committed.empty()) return std::nullopt;
802	      for (const auto pc: committed[0]) {
803	        auto state = hybrid_handoff_->on_retire(pc);
804	        if (state) {
805	          // V-register merge: pull the V dump sweep's scratch bytes into the
806	          // drained state (see lift_scratch_blocks).
807	          lift_scratch_blocks(*state);
808	          spdlog::info("hybrid handoff: drained at pc=0x{:x}, writing {}",
809	                       pc, hybrid_state_path_);
810	          if (spdlog::should_log(spdlog::level::debug))
811	            log_hybrid_ops("drain", hybrid_drain_oplog_);
812	          std::ofstream f(hybrid_state_path_, std::ios::binary);
813	          f.write(reinterpret_cast<const char*>(&*state), sizeof(*state));
814	          // F5: the LM sidecars ride with every drain -- one producer for
815	          // the "state file plus sidecars" contract.
816	          dump_lm_sidecars(hybrid_state_path_);
817	          return hybrid::kExitHandoffToQemu;
818	        }
819	      }
820	      return std::nullopt;
821	    }
822	  }
823	
824	  void enable_waveform(const std::string& waveform_filename)
825	  {
826	    trace_.enable_waveform(cpu, waveform_filename);
827	  }
828	
829	  void enable_pc_trace(const std::string& filename)
830	  {
831	    trace_.enable_pc_trace(filename);
832	  }
833	
834	  void enable_kanata(const std::string& filename,
835	                     const std::string& objdump_file = "")
836	  {
837	    trace_.enable_kanata(cpu, filename, objdump_file);
838	  }
839	
840	  void enable_clarity(const std::string& filename,
841	                      const std::string& objdump_file = "")
842	  {
843	    trace_.enable_clarity(cpu, filename, objdump_file);
844	  }
845	
846	  auto get_cycles() -> std::uint64_t { return trace_.get_cycles(platform.clk); }
847	
848	  void log_committed_pcs() { trace_.log_committed_pcs(cpu); }
849	
850	  void set_mem_latency(const uint32_t latency)
851	  {
852	    platform.main_memory.latency = latency;
853	  }
854	};
