// ---- hybrid OpLog rendering (V1/V2/V3) -------------------------------------
// The transport layers record pure per-op events (hybrid/op_log.hpp); these
// helpers render them through spdlog. debug: a per-block summary plus each
// tolerated cmderr with the regno it fired on. trace: every semantic op.

inline auto hybrid_op_kind_name(hybrid::OpLog::Kind k) -> const char*
{
  using Kind = hybrid::OpLog::Kind;
  switch (k) {
    case Kind::AbstractWrite: return "abstract-write";
    case Kind::AbstractRead:  return "abstract-read";
    case Kind::ProgBuf:       return "progbuf-exec";
    case Kind::PbFallback:    return "pb-fallback";
    case Kind::CmdErr:        return "cmderr";
  }
  return "?";
}

inline void log_hybrid_ops(const char* phase, const hybrid::OpLog& log)
{
  using Kind = hybrid::OpLog::Kind;
  std::size_t gpr = 0, fpr = 0, csr = 0, reads = 0, pb = 0, fb = 0, err = 0;
  for (const auto& e : log.events) {
    switch (e.kind) {
      case Kind::AbstractWrite:
        // Abstract regno classes: 0x1000+ GPR, 0x1020+ FPR, else CSR.
        if (e.regno >= 0x1020) ++fpr;
        else if (e.regno >= 0x1000) ++gpr;
        else ++csr;
        break;
      case Kind::AbstractRead: ++reads; break;
      case Kind::ProgBuf:      ++pb;    break;
      case Kind::PbFallback:   ++fb;    break;
      case Kind::CmdErr:       ++err;   break;
    }
  }
  spdlog::debug("hybrid: {} ops: {} gpr / {} fpr / {} csr abstract writes, "
                "{} abstract reads, {} progbuf execs, {} pb fallbacks, "
                "{} cmderr",
                phase, gpr, fpr, csr, reads, pb, fb, err);
  for (const auto& e : log.events)
    if (e.kind == Kind::CmdErr)
      spdlog::debug("hybrid: {}: cmderr={} on regno=0x{:x} (tolerated)",
                    phase, e.value, e.regno);
  if (!spdlog::should_log(spdlog::level::trace)) return;
  for (const auto& e : log.events)
    spdlog::trace("hybrid: {}: {} regno=0x{:x} value=0x{:x}",
                  phase, hybrid_op_kind_name(e.kind), e.regno, e.value);
}

// V3: on a resume abort the tail of the op log IS the forensic trail -- it
// names the register/CSR the transport was touching when it died.
inline void log_hybrid_abort_tail(const hybrid::OpLog& log)
{
  const std::size_t n = log.events.size();
  spdlog::error("hybrid: resume aborted after {} transport ops; last ops:", n);
  const std::size_t from = n > 8 ? n - 8 : 0;
  for (std::size_t i = from; i < n; ++i) {
    const auto& e = log.events[i];
    spdlog::error("hybrid:   [{}] {} regno=0x{:x} value=0x{:x}",
                  i, hybrid_op_kind_name(e.kind), e.regno, e.value);
  }
  spdlog::error("hybrid: re-run with --log-level 0 for the full per-op trace");
}

// Local-memory backdoor capabilities of a cpu wrapper -- the ONE authority
// for "can this engine load/dump ILM/DLM content" (LM transport,
// ROADMAP_ilm_dlm). load_image, dump_lm_sidecars, and main's describe gate
// all read these, so the advertise side and the load/dump sides cannot
// drift. Variable templates so the requires-expressions sit in a DEPENDENT
// context: a wrapper without the member SFINAEs to false, where the same
// expression written non-dependently is a hard compile error.
template <typename CPU>
inline constexpr bool kCpuCanLoadIlm = requires(CPU& c) { c.set_ilm({}); };
template <typename CPU>
inline constexpr bool kCpuCanLoadDlm = requires(CPU& c) { c.set_dlm({}); };
template <typename CPU>
inline constexpr bool kCpuCanDumpIlm = requires(CPU& c) { c.get_ilm(); };
template <typename CPU>
inline constexpr bool kCpuCanDumpDlm = requires(CPU& c) { c.get_dlm(); };
// Same authority pattern for the HVM backdoor (HVM transport, ROADMAP_hvm).
template <typename CPU>
inline constexpr bool kCpuCanLoadHvm = requires(CPU& c) { c.set_hvm({}); };
template <typename CPU>
inline constexpr bool kCpuCanDumpHvm = requires(CPU& c) { c.get_hvm(); };

template<typename CPU>
class Simulator : sc_core::sc_module
{
  using PLATFORM = Platform<platform_config<CPU>>;
  static constexpr bool is_axi = (CPU::SYSTEM_BUS_TYPE == BusTypes::AXI);
  static constexpr auto bus_width = PLATFORM::data_width;

  // Helper: create an AXI→TLM bridge, bind clock, connect initiator BFM
  auto make_axi_to_tlm(const char* name, auto& bfm_socket)
    -> std::unique_ptr<axi_to_tlm_bridge<bus_width>>
  {
    auto bridge = std::make_unique<axi_to_tlm_bridge<bus_width>>(name);
    bridge->pe.clk_i.bind(platform.clk);
    bfm_socket.bind(bridge->axi_tsck);
    return bridge;
  }

  // Helper: create a TLM→AXI bridge, bind clock, connect target BFM
  auto make_tlm_to_axi(const char* name, auto& bfm_socket)
    -> std::unique_ptr<tlm_to_axi_bridge<bus_width>>
  {
    auto bridge = std::make_unique<tlm_to_axi_bridge<bus_width>>(name);
    bridge->pe.clk_i.bind(platform.clk);
    bridge->axi_isck.bind(bfm_socket);
    return bridge;
  }

public:
  CPU cpu;
  PLATFORM platform;

  // AXI bridges (only used when is_axi == true, null otherwise)
  std::unique_ptr<axi_to_tlm_bridge<bus_width>> mem_bridge;
  std::unique_ptr<axi_to_tlm_bridge<bus_width>> mmio_bridge;
  std::unique_ptr<tlm_to_axi_bridge<bus_width>> hvm_bridge;
  std::unique_ptr<tlm_to_axi_bridge<bus_width>> slv_bridge;

  // sys bus (64-bit slave port on CPU, needs width adapter to 256-bit
  // interconnect)
  static constexpr std::size_t sys_bus_width = 64;
  std::unique_ptr<socket_width_adapter<bus_width, sys_bus_width>> sys_adapter;
  std::unique_ptr<tlm_to_axi_bridge<sys_bus_width>> sys_bridge;

#if _NDS_IOCP_NUM > 0
  // iocp_master connects directly to CPU, not through the interconnect.
  // It needs to speak the CPU's bus protocol.
  using IocpInitiatorType = std::
    conditional_t<is_axi, AxiPeInitiator<bus_width>, AhbPeInitiator<bus_width>>;
  IocpInitiatorType iocp_master;
#endif // _NDS_IOCP_NUM

private:
  // debug
  jtag_dtm& dtm;
  bool dtm_debug = false;
  TraceController<CPU> trace_;

  // Hybrid handoff. Order matters: dmi_bus_ is referenced by
  // handoff_, so it must be declared first.
  std::unique_ptr<hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width,
                                        PLATFORM::dmi_data_width>>
    hybrid_dmi_bus_;
  std::optional<hybrid::HandoffController<hybrid::CsrTrigger>>
    hybrid_handoff_;
  std::string hybrid_state_path_;
  std::optional<hybrid_state_v1> hybrid_input_state_;
  hybrid::OpLog hybrid_drain_oplog_;  // V2: exit-drain op recorder (debug on)

  using xlen_t = std::conditional_t<CPU::NDS_XLEN <= 32, uint32_t, uint64_t>;

public:
  ContextManager<CPU> context_config;

  Simulator(const sc_core::sc_module_name& name,
            std::span<uint8_t> ram_buffer = {},
            MemoryRegion ram_region = {RAM_BASE, RAM_END},
            MemoryRegion ram_alias_region = {RAM_ALIAS_BASE, RAM_ALIAS_END})
      : sc_core::sc_module{name},
        platform("platform", ram_buffer, ram_region, ram_alias_region),
        dtm(platform.dtm)
  {
    cpu.bind(platform.clk, platform.resetn, platform.reset_vector,
             platform.dmi_signals, platform.wfi_signal, platform.int_trigger);

    // --- CPU memory BFM → interconnect ---
    if constexpr (is_axi) {
      mem_bridge = make_axi_to_tlm("mem_bridge", cpu.mem_bfm.isckt);
      platform.interconnect.bind_initiator(mem_bridge->tlm_isck);
    } else {
      platform.interconnect.bind_initiator(cpu.mem_bfm.isckt);
    }

    // --- CPU MMIO BFM → interconnect ---
    if constexpr (requires { cpu.mmio_bfm; }) {
      if constexpr (is_axi) {
        mmio_bridge = make_axi_to_tlm("mmio_bridge", cpu.mmio_bfm.isckt);
        platform.interconnect.bind_initiator(mmio_bridge->tlm_isck);
      } else {
        platform.interconnect.bind_initiator(cpu.mmio_bfm.isckt);
      }
    }

    // --- CPU HVM subordinate port ---
    if constexpr (requires { cpu.hvm_bfm; }) {
      if constexpr (is_axi) {
        hvm_bridge = make_tlm_to_axi("hvm_bridge", cpu.hvm_bfm.tsckt);
        platform.interconnect.bind_target(
          hvm_bridge->tlm_tsck,
          hvm_aperture(CPU::NDS_HVM_BASE, CPU::NDS_HVM_SIZE_KB));
      } else {
        platform.interconnect.bind_target(
          cpu.hvm_bfm.tsckt,
          hvm_aperture(CPU::NDS_HVM_BASE, CPU::NDS_HVM_SIZE_KB));
      }
    }

    // --- CPU slave port ---
    if constexpr (requires { cpu.slv_bfm; }) {
      if constexpr (is_axi) {
        slv_bridge = make_tlm_to_axi("slv_bridge", cpu.slv_bfm.tsckt);
        platform.interconnect.bind_target(slv_bridge->tlm_tsck,
                                          {HART0_ILM_BASE, HART0_DLM_END});
      } else {
        platform.interconnect.bind_target(cpu.slv_bfm.tsckt,
                                          {HART0_ILM_BASE, HART0_DLM_END});
      }
    }

    // --- CPU sys bus (slave port, 64-bit) → interconnect ---
    if constexpr (requires { cpu.sys_bfm; }) {
      sys_adapter =
        std::make_unique<socket_width_adapter<bus_width, sys_bus_width>>(
          "sys_adapter");
      sys_bridge =
        std::make_unique<tlm_to_axi_bridge<sys_bus_width>>("sys_bridge");
      sys_bridge->pe.clk_i.bind(platform.clk);
      sys_bridge->axi_isck.bind(cpu.sys_bfm.tsckt);
      sys_adapter->isck.bind(sys_bridge->tlm_tsck);
      platform.interconnect.bind_target(sys_adapter->tsck,
                                        {MLIF_BASE, SLIF_END});
    }

#if _NDS_IOCP_NUM > 0
    iocp_master.protocol_engine.clk_i.bind(platform.clk);
    iocp_master.socket.bind(cpu.iocp_bfm.tsckt);
#endif // _NDS_IOCP_NUM
  }

  ~Simulator() { trace_.close(); }

  void init_debug_port(const uint16_t port = 9104)
  {
    dtm_debug = true;
    dtm.init_port(port);
    spdlog::info("waiting for debugger connection");
  }

  // Caller invariant: the CPU must already be out of reset.
  //
  // baseline_cache (LG3): path to this (engine build, ELF)'s reset-state
  // baseline; empty disables the liveness gate (transport-everything). On a
  // cache miss the baseline is captured HERE: the hart is freshly reset and
  // the capture drain halts it exactly where resume() would, so the drained
  // values ARE what the gate must compare restores against. Capture runs
  // BEFORE the scratch stagings below -- its drain sweeps dump reset
  // registers through the same scratch page the stagings fill.
  void apply_resume_from_qemu(const std::string& path,
                              const std::string& baseline_cache = {})
  {
    hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width, PLATFORM::dmi_data_width>
      bus{platform.dmi, platform.clk.period()};
    hybrid_input_state_ = hybrid::load_state(path);

    std::optional<hybrid_state_v1> baseline{};
    bool baseline_captured = false;
    if (!baseline_cache.empty()) {
      baseline = hybrid::try_load_reset_baseline(baseline_cache);
      // Stale-shape insurance: a cache whose flags/vlenb no longer cover the
      // incoming state was captured under a different engine/QEMU pairing.
      if (baseline
          && ((baseline->flags & hybrid_input_state_->flags)
                != hybrid_input_state_->flags
              || baseline->vlenb != hybrid_input_state_->vlenb))
        baseline.reset();
      if (!baseline) {
        baseline = capture_reset_baseline(bus, *hybrid_input_state_);
        baseline_captured = true;
        if (!hybrid::save_reset_baseline(baseline_cache, *baseline))
          spdlog::warn("hybrid: cannot save reset baseline to {}",
                       baseline_cache);
      }
      spdlog::info("hybrid: reset baseline {} ({})",
                   baseline_captured
                     ? "captured -- one-time cost per engine build + ELF"
                     : "cache hit",
                   baseline_cache);
    }

    // Stage V-register bytes into the fixed scratch region of RAM BEFORE
    // resume: ResumeDriver's Program-Buffer reload sweep issues vle8.v from
    // this region to repopulate v0..v31, so the bytes must be in place first.
    // Best-effort: mismatched RAM layouts throw, which is louder than silently
    // dropping V state.
    if ((hybrid_input_state_->flags & HYBRID_FLAG_V) != 0u) {
      hybrid::stage_v_to_scratch(*hybrid_input_state_,
                                 platform.main_memory.data);
    }
    // GPR/FPR/CSR transport is Abstract-Command-only in BOTH directions (never
    // Program Buffer): a csrrw to a caps-supported but read-only / WARL-illegal
    // CSR raises cmderr, and the abstract path's per-CSR clear_cmderr tolerates
    // that single failure and moves on -- a batched PB sweep could not. The
    // Program Buffer carries only what abstract commands cannot reach: the V
    // data sweep, the Tier-B vsetvl, and the L2C MMIO window.
    const auto caps = active_caps();
    hybrid::ResumeDriver driver(bus, v_scratch_gpa(), caps);
    driver.set_l2c(l2c_present(), l2c_base());  // v5: restore L2C config if present
    // LG3: on a capture run the capture drain's V dump sweep clobbered
    // vtype/vl/vstart, so the vsetvl elision is only valid on cache hits.
    if (baseline)
      driver.set_reset_baseline(*baseline,
                                /*v_cfg_at_reset=*/!baseline_captured);
    std::size_t andes_mext_csrs = 0;
    hybrid::for_each_transport_csr(*hybrid_input_state_, caps,
      [&](uint16_t, const uint64_t&) { ++andes_mext_csrs; });
    // V1/V2: record the transport ops when debug is on; V3: on an abort the
    // op-log tail names the register/CSR the restore died on.
    hybrid::OpLog oplog;
    const bool log_ops = spdlog::should_log(spdlog::level::debug);
    if (log_ops) driver.set_op_log(&oplog);
    const auto resume_t0 = sc_core::sc_time_stamp();
    const auto wall_t0 = std::chrono::steady_clock::now();
    try {
      driver.resume(*hybrid_input_state_);
    } catch (const std::exception&) {
      if (log_ops) log_hybrid_abort_tail(oplog);
      throw;
    }
    const auto wall_ms = std::chrono::duration_cast<std::chrono::milliseconds>(
      std::chrono::steady_clock::now() - wall_t0).count();
    const auto resume_cycles = static_cast<uint64_t>(
      (sc_core::sc_time_stamp() - resume_t0) / platform.clk.period());
    spdlog::info("hybrid: resume={} cycles ({} ms wall), restore path="
                 "abstract, andes+m-ext csrs={}",
                 resume_cycles, wall_ms, andes_mext_csrs);
    if (baseline)
      spdlog::info("hybrid: liveness gate elided {} register restores",
                   driver.baseline_skip_count());
    if (log_ops) log_hybrid_ops("resume", oplog);
  }

  // F3: standalone CSR existence + reset-value probe. Halts the freshly-reset
  // hart via DMI and checked-reads each address -- cmderr (an unimplemented
  // CSR) surfaces as nullopt. No QEMU state, no run(): the read values ARE the
  // architectural reset state. Emitted by `--probe`, consumed by andesim's
  // gen_manifest.py to MEASURE the implemented set + reset values instead of
  // hand-tracing RTL params. The caller must load a (spin) ELF first so the
  // reset vector is mapped -- the hart fetches a couple instructions from it
  // before the DMI halt takes effect (same window capture_reset_baseline uses).
  auto probe_csrs(const std::vector<uint16_t>& addrs)
    -> std::vector<std::pair<uint16_t, std::optional<uint64_t>>>
  {
    using RD = hybrid::ResumeDriver;
    hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width, PLATFORM::dmi_data_width>
      bus{platform.dmi, platform.clk.period()};
    bus.write(RD::kDmcontrol, RD::kDmcontrolDmactive);
    bus.write(RD::kDmcontrol, RD::kDmcontrolDmactive | RD::kDmcontrolHaltreq);
    hybrid::poll_until_set(bus, RD::kDmstatus, RD::kDmstatusAllhalted,
                           "csr-probe halt");
    // At reset mstatus.FS/VS are Off, so FP/V CSR reads raise illegal-insn
    // (cmderr) and would mis-probe as absent. Enable them (WARL no-op on an
    // engine without FP/V), exactly like capture_reset_baseline before its
    // FP/V reads. mstatus's own probed value is thus FS/VS-perturbed -- a known
    // artifact (mstatus is a base always-transported, verify-excluded CSR).
    {
      const uint64_t mstatus = hybrid::read_register_64(
        bus, hybrid::regno_csr(RD::kCsrMstatus), "csr-probe mstatus");
      uint64_t enable = mstatus;
      if ((enable & RD::kMstatusFsMask) == 0) enable |= RD::kMstatusFsInitial;
      if ((enable & RD::kMstatusVsMask) == 0) enable |= RD::kMstatusVsInitial;
      if (enable != mstatus)
        hybrid::write_register_abstract(
          bus, hybrid::regno_csr(RD::kCsrMstatus), enable);
    }
    std::vector<std::pair<uint16_t, std::optional<uint64_t>>> out;
    out.reserve(addrs.size());
    for (const uint16_t a: addrs)
      out.emplace_back(a, hybrid::read_register_64_checked(
                            bus, hybrid::regno_csr(a), "csr-probe"));
    return out;
  }

  // Enables the vsim->QEMU handoff drain. After this is set, run() watches
  // committed PCs and on retire of the `slti x0, x0, 0x5A1` exit marker drains
  // architectural state to `state_out_path` and returns kExitHandoffToQemu.
  //
  // When `exit_pc` is set, the trigger is populated by `add_pc_hit` (PC
  // mode) and the ELF scan is skipped: the binary need not contain a marker
  // HINT. Marker mode and PC mode are mutually exclusive on a single run --
  // callers pass exactly one form.
  void enable_hybrid_handoff(const std::string& elf_path,
                             const std::string& state_out_path,
                             std::optional<uint64_t> exit_pc = std::nullopt,
                             bool drain_minimal = false)
  {
    hybrid::CsrTrigger trigger;
    if (exit_pc) {
      trigger.add_pc_hit(*exit_pc, HYBRID_HANDOFF_EXIT);
      spdlog::info("hybrid: PC-trigger mode, exit_pc=0x{:x}", *exit_pc);
    } else {
      auto elf = LIEF::ELF::Parser::parse(elf_path);
      if (!elf)
        throw std::runtime_error(
          "enable_hybrid_handoff: failed to parse " + elf_path);
      for (const auto& seg: elf->segments()) {
        if (seg.type() != LIEF::ELF::SEGMENT_TYPES::PT_LOAD) continue;
        if ((static_cast<unsigned>(seg.flags()) & 1u) == 0u) continue;  // PF_X
        const auto content = seg.content();
        const std::span<const uint8_t> bytes{content.data(), content.size()};
        trigger.scan_buffer(bytes, seg.virtual_address());
      }
    }

    hybrid_dmi_bus_ = std::make_unique<
      hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width,
                            PLATFORM::dmi_data_width>>(platform.dmi,
                                                       platform.clk.period());
    hybrid_handoff_.emplace(std::move(trigger), *hybrid_dmi_bus_,
                            v_scratch_gpa(), active_caps());
    if (hybrid_input_state_)
      hybrid_handoff_->set_passthrough_input(*hybrid_input_state_);
    hybrid_handoff_->set_minimal_drain(drain_minimal);
    hybrid_handoff_->set_l2c(l2c_present(), l2c_base());  // v5: exit drain re-reads L2C
    // V2: record the exit drain's ops when debug is on (rendered at the
    // drain site in check_hybrid_handoff).
    if (spdlog::should_log(spdlog::level::debug))
      hybrid_handoff_->set_op_log(&hybrid_drain_oplog_);

    hybrid_state_path_ = state_out_path;
  }

  // F6: override the config-derived caps with a manifest-driven transport set
  // (from --transport-csrs). When set, active_caps() returns this instead of
  // andes_caps_from_config() -- the runtime transport is then driven by the
  // registered manifest, not by re-modelling config macros.
  void set_transport_caps(const hybrid::AndesCaps& c) { transport_caps_ = c; }

private:
  std::optional<hybrid::AndesCaps> transport_caps_{};
  auto active_caps() const -> hybrid::AndesCaps
  {
    return transport_caps_ ? *transport_caps_ : hybrid::andes_caps_from_config();
  }

  // v5: L2C MMIO transport gate, derived from the build's Verilog config macros
  // (_NDS_*, supplied via cpu_config.hpp -- same source as andes_caps_from_
  // config). Present only when this engine is built with an L2 cache controller
  // AND its register base is known. Gated on _NDS_L2C_CACHE_SIZE_KB, not the
  // cluster's has_shared_cache, because that flag also covers L3 (ax46/ax66).
  // A store to an absent L2C region would fault the Program Buffer, so this
  // stays off on every current engine (_NDS_L2C_CACHE_SIZE_KB == 0).
  static constexpr bool l2c_present()
  {
#if defined(_NDS_L2C_CACHE_SIZE_KB) && defined(_NDS_L2C_REG_BASE)
    return (_NDS_L2C_CACHE_SIZE_KB) > 0;
#else
    return false;
#endif
  }
  static constexpr uint64_t l2c_base()
  {
#if defined(_NDS_L2C_REG_BASE)
    return static_cast<uint64_t>(_NDS_L2C_REG_BASE);
#else
    return 0;
#endif
  }

  // L26: the GUEST address of the V-register transport page -- the top page of
  // the mapped RAM span. The driver maps one page above --mem-size (scheme D),
  // so this sits just past the program's declared RAM and never collides with
  // its data/stack. Single source of truth handed to ResumeDriver/StateDrain.
  auto v_scratch_gpa() const -> uint64_t
  {
    return hybrid::v_scratch_gpa(platform.main_memory.region.base_address,
                                 platform.main_memory.data.size());
  }

  // LG3: drain the freshly reset, just-halted hart into a baseline the
  // liveness gate compares restores against. The probe carries the incoming
  // state's flags/vlenb so drain_with_passthrough reads exactly the blocks
  // the gate will compare (it is flag-driven); every probe field it does not
  // re-read stays zero, matching what an absent block compares against.
  auto capture_reset_baseline(
    hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width,
                          PLATFORM::dmi_data_width>& bus,
    const hybrid_state_v1& input) -> hybrid_state_v1
  {
    hybrid::StateDrain drain(bus, v_scratch_gpa(),
                             active_caps());
    // At reset mstatus.FS/VS are Off, so the capture's vse8 sweep (and the
    // FPR/V CSR abstract reads) would raise illegal instruction (cmderr=3).
    // Halt and enable them first, exactly like resume() does before its FPR/V
    // writes. Safe to clobber: mstatus is never re-read by a drain nor gated
    // by the baseline, and resume() rewrites it whenever the FP/V flags are
    // set -- the only case this branch runs.
    if (input.flags & (HYBRID_FLAG_FP | HYBRID_FLAG_V)) {
      using RD = hybrid::ResumeDriver;
      bus.write(RD::kDmcontrol, RD::kDmcontrolDmactive);
      bus.write(RD::kDmcontrol,
                RD::kDmcontrolDmactive | RD::kDmcontrolHaltreq);
      hybrid::poll_until_set(bus, RD::kDmstatus, RD::kDmstatusAllhalted,
                             "reset-baseline capture halt");
      const uint64_t mstatus = hybrid::read_register_64(
        bus, hybrid::regno_csr(RD::kCsrMstatus), "reset-baseline mstatus");
      uint64_t enable = mstatus;
      if ((input.flags & HYBRID_FLAG_FP)
          && (enable & RD::kMstatusFsMask) == 0)
        enable |= RD::kMstatusFsInitial;
      if ((input.flags & HYBRID_FLAG_V)
          && (enable & RD::kMstatusVsMask) == 0)
        enable |= RD::kMstatusVsInitial;
      if (enable != mstatus)
        hybrid::write_register_abstract(
          bus, hybrid::regno_csr(RD::kCsrMstatus), enable);
    }
    hybrid_state_v1 probe{};
    probe.magic = HYBRID_STATE_MAGIC;
    probe.version = HYBRID_STATE_VERSION;
    probe.flags = input.flags;
    probe.vlenb = input.vlenb;
    auto baseline = drain.drain_with_passthrough(probe);
    lift_scratch_blocks(baseline);
    return baseline;
  }

  // Lift the scratch-page transport into `state` (dual of the resume
  // staging): the V dump sweep bytes back into state.vreg[] -- so the drained
  // state carries vsim's actual V values, not QEMU 1's stale snapshot. The V
  // regfile is the only state that rides the scratch page; GPRs, FPRs, and
  // every CSR drain via abstract reads directly into the state. Shared by the
  // exit drain and the reset-baseline capture.
  void lift_scratch_blocks(hybrid_state_v1& state)
  {
    const std::span<const uint8_t> ram{platform.main_memory.data.data(),
                                       platform.main_memory.data.size()};
    if ((state.flags & HYBRID_FLAG_V) != 0u)
      hybrid::read_v_from_scratch(state, ram);
  }

public:

  void restore_context(const std::string& dir)
  {
    context_config.dir = dir;
    context_config.restore(platform, cpu);
  }

  // skip_memory_load: parse the ELF and set the reset vector, but leave
  // platform.main_memory untouched. Used in tier-2 hybrid resume where
  // QEMU 1's -kernel already populated the shared mmap; re-loading would
  // zero-fill the .bss tail of each PT_LOAD and destroy phase-1 writes
  // to static buffers. The reset vector is still set so the hart has a
  // valid fetch target during the post-reset cycles that precede the DMI
  // halt+DPC-write resume sequence.
  void load_elf(const std::string& path, bool skip_memory_load = false)
  {
    const auto elf = LIEF::ELF::Parser::parse(path);
    if (!elf) {
      spdlog::critical("Check if it's a valid ELF file path : {}", path);
      exit(1);
    }

    if (!skip_memory_load)
      read_elf_into_memory(
        *elf,
        static_cast<xlen_t>(platform.main_memory.region.base_address),
        platform.main_memory.data);
    for (auto& rv: platform.reset_vector)
      rv.write(elf->entrypoint());
  }

  void set_reset_vector(size_t hart, uint64_t addr)
  {
    if (hart >= platform.reset_vector.size()) {
      spdlog::critical("hart {} out of range (max {})", hart,
                       platform.reset_vector.size() - 1);
      std::exit(EXIT_FAILURE);
    }
    platform.reset_vector[hart].write(addr);
  }

  // F5 (ROADMAP_ilm_dlm) + F4 (ROADMAP_hvm): dump the local memories' and
  // HVM's content next to the handoff-out state file -- the read duals of
  // the --ilm/--dlm/--hvm backdoor load, same "<state>.ilm/.dlm/.hvm"
  // sidecar convention as the QEMU plugin's entry drain. Zero sim cycles
  // (hierarchical-reference read, ECC stripped). A wrapper without the
  // get_* dumps nothing. Called by check_hybrid_handoff right after the
  // state-file write, so the "state file plus sidecars ride together"
  // contract has a single producer.
  void dump_lm_sidecars(const std::string& state_path)
  {
    auto dump = [](const std::string& path, const std::vector<uint8_t>& data) {
      std::ofstream f(path, std::ios::binary | std::ios::trunc);
      f.write(reinterpret_cast<const char*>(data.data()),
              static_cast<std::streamsize>(data.size()));
      if (!f) throw std::runtime_error("cannot write " + path);
    };
    if constexpr (kCpuCanDumpIlm<CPU>)
      dump(state_path + ".ilm", cpu.get_ilm());
    if constexpr (kCpuCanDumpDlm<CPU>)
      dump(state_path + ".dlm", cpu.get_dlm());
    if constexpr (kCpuCanDumpHvm<CPU>)
      dump(state_path + ".hvm", cpu.get_hvm());
  }

  void load_image(const std::string& path, MEM_TYPE type)
  {
    switch (type) {
    case MEM_TYPE::ILM:
      if constexpr (kCpuCanLoadIlm<CPU>) {
        read_binary_file(path, [this](const auto& data) { cpu.set_ilm(data); });
      } else {
        throw std::runtime_error(
          "CPU does not support ILM - cannot load ILM ROM image");
      }
      break;

    case MEM_TYPE::DLM:
      if constexpr (kCpuCanLoadDlm<CPU>) {
        read_binary_file(path, [this](const auto& data) { cpu.set_dlm(data); });
      } else {
        throw std::runtime_error(
          "CPU does not support DLM - cannot load DLM ROM image");
      }
      break;

    case MEM_TYPE::HVM:
      if constexpr (kCpuCanLoadHvm<CPU>) {
        read_binary_file(path, [this](const auto& data) { cpu.set_hvm(data); });
      } else {
        throw std::runtime_error(
          "CPU does not support HVM - cannot load HVM image");
      }
      break;

    case MEM_TYPE::RAM:
      read_binary_file(path, [this](const auto& data) {
        if (data.size() > platform.main_memory.data.size())
          throw std::runtime_error("RAM image size exceeds main memory size");
        std::copy(data.begin(), data.end(), platform.main_memory.data.begin());
      });
      break;

    default:
      throw std::runtime_error("Unknown memory type");
    }
  }

  void reset()
  {
    static constexpr int core_num = CPU::NDS_NHART;
    static constexpr int reset_val = (1 << core_num) - 1;

    platform.resetn.write(0);
    auto saved = context_config;
    context_config = {};
    this->run(1);
    context_config = saved;

    for (size_t i = 0; i < platform.reset_vector.size(); ++i)
      spdlog::info("hart {} reset vector: {:#x}", i,
                   (uint64_t) platform.reset_vector[i].read());

    platform.resetn.write(reset_val);

    if (context_config.continue_from)
      restore_context(context_config.dir);
  }

  int run(const uint64_t max_cycles = std::numeric_limits<uint64_t>::max())
  {
    auto sa = memzeroed<struct sigaction>();
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);

    auto oact = memzeroed<struct sigaction>();
    if (sigaction(SIGINT, &sa, &oact) == -1)
      perror("sigaction");

    const auto restore_sigint = std::experimental::scope_exit{[&] {
      if (sigaction(SIGINT, &oact, nullptr) == -1)
        perror("sigaction");
    }};

    // wait for debugger connections
    while (dtm_debug && !dtm.is_connected()) {
      dtm.try_accept_socket();
      if (ctrlc != 0) {
        return 130;
      }
      sleep(1);
    }

    [[maybe_unused]]
    bool ctx_resuming = context_config.continue_from;
    [[maybe_unused]]
    bool ctx_triggered = false;

    for (auto n = uint64_t{0}; n < max_cycles; ++n) {

      if (ctx_resuming) [[unlikely]] {
        // Pull up PLIC interrupt signal at the first cycle of the resume
        platform.int_trigger.write(1);
        ctx_resuming = false;
        ctx_triggered = true;
      }

      sc_core::sc_start(platform.clk.period());

      trace_.on_cycle(cpu);

      if (hybrid_handoff_) [[unlikely]] {
        if (auto code = check_hybrid_handoff(); code) return *code;
      }

      if (context_config.save_on_wfi && platform.wfi_signal.read() == true)
        [[unlikely]]
      {
        context_config.save(platform, cpu);
        spdlog::info("User save context");
        return 0;
      }

      if (ctrlc != 0) {
        ctrlc = 0;
        spdlog::info("Ctrl+C PC: {:x}", get_current_pc());
        trace_.log_committed_pcs(cpu);
        return 130;
      }

      if (ctx_triggered) [[unlikely]] {
        // Pull down the interrupt signal after 1 cycle
        platform.int_trigger.write(0);
        ctx_triggered = false;
      }

      if (platform.sim_control.exits >= 0) {
        spdlog::info("sim_control: got exit {}, stopping",
                     platform.sim_control.exits);
        spdlog::info("Exit PC: {:x}", get_current_pc());
        trace_.log_committed_pcs(cpu);
        return platform.sim_control.exits;
      }

      if (this->cpu.contextp()->gotFinish())
        return 0;

      spdlog::trace("PC: {:x}", get_current_pc());
    }
    return 0;
  }

  uint64_t get_current_pc()
  {
    if constexpr (requires { cpu.get_current_pc(); }) {
      return cpu.get_current_pc();
    }
    return std::numeric_limits<uint64_t>::max();
  }

  auto check_hybrid_handoff() -> std::optional<int>
  {
    if constexpr (!requires { cpu.get_committed_pc(); }) {
      return std::nullopt;
    } else {
      const auto committed = cpu.get_committed_pc();
      if (committed.empty()) return std::nullopt;
      for (const auto pc: committed[0]) {
        auto state = hybrid_handoff_->on_retire(pc);
        if (state) {
          // V-register merge: pull the V dump sweep's scratch bytes into the
          // drained state (see lift_scratch_blocks).
          lift_scratch_blocks(*state);
          spdlog::info("hybrid handoff: drained at pc=0x{:x}, writing {}",
                       pc, hybrid_state_path_);
          if (spdlog::should_log(spdlog::level::debug))
            log_hybrid_ops("drain", hybrid_drain_oplog_);
          std::ofstream f(hybrid_state_path_, std::ios::binary);
          f.write(reinterpret_cast<const char*>(&*state), sizeof(*state));
          // F5: the LM sidecars ride with every drain -- one producer for
          // the "state file plus sidecars" contract.
          dump_lm_sidecars(hybrid_state_path_);
          return hybrid::kExitHandoffToQemu;
        }
      }
      return std::nullopt;
    }
  }

  void enable_waveform(const std::string& waveform_filename)
  {
    trace_.enable_waveform(cpu, waveform_filename);
  }

  void enable_pc_trace(const std::string& filename)
  {
    trace_.enable_pc_trace(filename);
  }

  void enable_kanata(const std::string& filename,
                     const std::string& objdump_file = "")
  {
    trace_.enable_kanata(cpu, filename, objdump_file);
  }

  void enable_clarity(const std::string& filename,
                      const std::string& objdump_file = "")
  {
    trace_.enable_clarity(cpu, filename, objdump_file);
  }

  auto get_cycles() -> std::uint64_t { return trace_.get_cycles(platform.clk); }

  void log_committed_pcs() { trace_.log_committed_pcs(cpu); }

  void set_mem_latency(const uint32_t latency)
  {
    platform.main_memory.latency = latency;
  }
};

